import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
from datetime import datetime, timezone


def plan(root):
    updates={}
    for rel,text in SPEC['files'].items():
        p=root/rel
        if p.is_symlink() or root not in p.resolve().parents:
            raise SystemExit('UNSAFE_PATH: '+rel)
        if p.exists() and p.read_text()!=text:
            raise SystemExit('NEW_MODULE_CONFLICT: '+rel+'; files not changed')
        if not p.exists():updates[rel]=text
    grouped={}
    for item in SPEC['patches']:grouped.setdefault(item['path'],[]).append(item)
    for rel,patches in grouped.items():
        p=root/rel
        if not p.is_file() or p.is_symlink() or root not in p.resolve().parents:
            raise SystemExit('MISSING_OR_UNSAFE_FILE: '+rel)
        old=p.read_text();text=old
        for change in patches:
            if change['new'] in text:continue
            if text.count(change['old'])!=1:
                raise SystemExit('SOURCE_VERSION_CONFLICT: '+rel+'; files not changed')
            text=text.replace(change['old'],change['new'],1)
        if text!=old:updates[rel]=text
    for rel,text in updates.items():compile(text,rel,'exec')
    return updates


def run(args):
    print('RUN:', ' '.join(args),flush=True)
    subprocess.run(args,check=True)


def main():
    parser=argparse.ArgumentParser(description='Roseltorg / ESTP / Acron bounded pipeline installer')
    parser.add_argument('--check',action='store_true',help='Validate source compatibility without writes')
    parser.add_argument('--no-run',action='store_true',help='Keep schedules, but do not submit initial collection')
    args=parser.parse_args();root=Path.cwd().resolve()
    if not (root/'app/main.py').is_file():raise SystemExit('Run from project root: tender-ai-platform-v6.2')
    for rel in ('app/sources/gpb/archives.py','app/sources/tektorg/backlog.py','app/reports/review_dashboard.py',
                'app/workers/tasks_primary_discovery.py','app/workers/completed_analysis.py'):
        if not (root/rel).is_file():raise SystemExit('MISSING_DEPENDENCY: '+rel)
    changes=plan(root)
    print('FILES_TO_UPDATE:',len(changes),flush=True)
    print('Roseltorg: public documents -> OCR -> LLM. ESTP: verified EIS 223-FZ identity -> same pipeline.')
    print('Acron: access/capability diagnostic only; blocked access cannot be made into a working adapter.')
    if args.check:return
    if changes:
        backup=Path(tempfile.mkdtemp(prefix='multi-platform-backup-',dir=root.parent))
        manifest=[]
        for rel,text in changes.items():
            p=root/rel;existed=p.exists()
            if existed:
                dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
            manifest.append({'path':rel,'existed':existed,'after':hashlib.sha256(text.encode()).hexdigest()})
        (backup/'manifest.json').write_text(json.dumps({'root':str(root),'files':manifest},indent=2))
        print('BACKUP:',backup,flush=True)
        written=[]
        try:
            for rel,text in changes.items():
                p=root/rel;p.parent.mkdir(parents=True,exist_ok=True)
                fd,tmp=tempfile.mkstemp(dir=p.parent)
                try:
                    with os.fdopen(fd,'w',encoding='utf-8') as f:f.write(text)
                    os.chmod(tmp,p.stat().st_mode&0o777 if p.exists() else 0o644)
                    os.replace(tmp,p);written.append(rel)
                finally:
                    if os.path.exists(tmp):os.unlink(tmp)
        except Exception:
            for rel in reversed(written):
                if (backup/rel).exists():shutil.copy2(backup/rel,root/rel)
                else:(root/rel).unlink(missing_ok=True)
            raise
    run(['docker','compose','build','app','celery_worker','celery_discovery'])
    # Tests run before replacing the running services. No real network/DB/LLM.
    run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-m','app.sources.multi_selftest'])
    run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-c',
         "from app.workers.tasks_primary_discovery import collect_primary; from app.workers.tasks_parsing import process_new_tender; from app.workers.tasks_scoring import analyze_tender; from app.sources.multi_manual import run_selected; from app.reports.review_dashboard import get_review_dashboard; print('PIPELINE_IMPORTS_OK')"])
    run(['docker','compose','up','-d','--no-deps','--timeout','900','app','celery_worker','celery_discovery'])
    print('MULTI_PLATFORM_PIPELINE_INSTALLED',flush=True)
    marker=root/'multi-platform-install-receipt.json'
    if not args.no_run and not marker.exists():
        # Existing collect_primary task and queues, no new scheduler entries.
        run(['docker','compose','exec','-T','celery_discovery','python','-c',
             "from app.workers.tasks_primary_discovery import collect_primary; "
             "[(print('QUEUED:', s, collect_primary.delay(s).id, flush=True)) for s in ('roseltorg','estp','acron')]"])
        marker.write_text(json.dumps({'version':'20261012-v1','submitted_at':datetime.now(timezone.utc).isoformat(),
            'sources':['roseltorg','estp','acron']},indent=2))
    print('Schedules retained. Max two new processing attempts per platform/run. Notifications suppressed.')
    print('Queued is not analyzed. Incomplete documents and unresolved LLM extraction stay in review.')


if __name__=='__main__':main()
